{"code": "export async function main(input: { project: string }) {
  const res = await sdk.sentry.listIssues({ project: input.project });
  return {
    total: res.issues.length,
    statuses: res.issues.map((i) => i.status),
    issues: res.issues.map((i) => ({ id: i.id, shortId: i.shortId, count: i.count, status: i.status })),
  };
}", "input": {"project": "jobs"}}

{"code": "export async function main(input: { project: string }) {
  const res = await sdk.sentry.listIssues({ project: input.project });
  const out = [];
  for (const issue of res.issues) {
    const ev = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    const newest = ev.events.length > 0 ? ev.events[0] : null;
    out.push({
      shortId: issue.shortId,
      count: issue.count,
      status: issue.status,
      latestRelease: newest ? newest.release : null,
      _newestTs: newest ? newest.timestamp : null,
      _n: ev.events.length,
    });
  }
  out.sort((a, b) => b.count - a.count);
  return out;
}", "input": {"project": "jobs"}}

{"code": "export async function main(input: { project: string }) {
  const res = await sdk.sentry.listIssues({ project: input.project });
  const debug = [];
  for (const issue of res.issues) {
    const ev = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    if (ev.events.length > 1) debug.push({ shortId: issue.shortId, events: ev.events });
  }
  return debug;
}", "input": {"project": "jobs"}}

{"code": "export async function main(input: { project: string; minCount?: number }) {
  const minCount = input.minCount ?? 0;
  const res = await sdk.sentry.listIssues({ project: input.project });
  const rows: { shortId: string; count: number; status: string; latestRelease: string | null }[] = [];
  for (const issue of res.issues) {
    if (!(issue.count >= minCount)) continue;
    const ev = await sdk.sentry.listIssueEvents({ issueId: issue.id });
    let newest: { timestamp: string; release: string } | null = null;
    for (const e of ev.events) {
      const t = Date.parse(e.timestamp);
      if (newest === null || t > Date.parse(newest.timestamp)) newest = { timestamp: e.timestamp, release: e.release };
    }
    rows.push({
      shortId: issue.shortId,
      count: issue.count,
      status: issue.status,
      latestRelease: newest === null ? null : newest.release,
    });
  }
  rows.sort((a, b) => b.count - a.count || a.shortId.localeCompare(b.shortId));
  return rows;
}", "input": {"project": "jobs", "minCount": 0}}
